static uint8_t ble_img, ble_boot_on, ble_up, ble_want, ble_host_on, ble_dead, ble_blocked;
static uint8_t ble_central_role, ble_role_changing, desired;
static ble_guard_t ble_guard;
static struct { uint32_t p3_rst, rst_src; } fm1_boot;
static uint32_t fm1_c1_wait_end, fm1_guard_xip_hi, fm1_guard_ram_hi;
static unsigned stacks;
static int smc_ble_role_get(void) { return desired; }
static void fm1_t5w_boot(void) { }
