static void ble_sink_check(void) { }
static void ble_wait_record(void) { }
static void fm1_cpu1_ble_stacks(uint32_t hi, uint32_t lo)
{ (void)hi; (void)lo; stacks++; }
#include "ble_toggle.inc"
static void reset(void)
{
    memset(&ble_r, 0, sizeof ble_r); memset(&ble_guard, 0, sizeof ble_guard);
    ble_img = ble_boot_on = ble_up = ble_want = ble_host_on = ble_dead = ble_blocked = 0;
    ble_central_role = ble_role_changing = 0; stacks = 0; image_status = BLE_IMG_OK;
}
int main(void)
{
    for (desired = 0; desired < 2; desired++) {
        reset(); ble_prepare(0);
        assert(ble_boot_on && !ble_want && !ble_host_on && stacks == 1);
        assert(ble_guard.trying && !ble_guard.blocked && plat_ble_state() == PLAT_BLE_OFF);
        /* RF init/attach is not simulated: publish its success as the platform input. */
        ble_guard_started(&ble_guard, 0, 1); ble_up = 1;
        plat_ble_set(1); assert(plat_ble_state() == PLAT_BLE_STARTING);
        for (unsigned i = 0; i < 100; i++) { plat_ble_set(0); plat_ble_set(1); }
        assert(stacks == 1 && ble_guard.trying && !ble_dead);
        plat_ble_set(0); assert(plat_ble_state() == PLAT_BLE_OFF);
        plat_ble_set(1); assert(plat_ble_state() != PLAT_BLE_RESTART);
    }
    for (int bad = BLE_IMG_NONE; bad <= BLE_IMG_BAD; bad++) {
        reset(); image_status = bad; ble_prepare(0); plat_ble_set(1);
        assert(!ble_boot_on && !stacks && !ble_guard.trying);
        assert(plat_ble_state() == (bad == BLE_IMG_NONE ? PLAT_BLE_NOIMG : PLAT_BLE_BADIMG));
    }
    reset(); ble_guard.magic = BLE_GUARD_MAGIC; ble_guard.trying = 1;
    ble_prepare(0); assert(ble_dead && ble_blocked && !stacks);
    assert(plat_ble_state() == PLAT_BLE_OFF);
    plat_ble_set(1); assert(plat_ble_state() == PLAT_BLE_FAILED);
    plat_ble_set(0); assert(!ble_guard.blocked && ble_dead);
    plat_ble_set(1); assert(plat_ble_state() == PLAT_BLE_FAILED && !stacks);
    reset(); ble_prepare(1); ble_guard_started(&ble_guard, -1, 0); ble_dead = 1;
    plat_ble_set(0); plat_ble_set(1);
    assert(ble_dead && plat_ble_state() == PLAT_BLE_FAILED && stacks == 1);
    puts("PASS actual boot/setter/state: OFF cold boot, repeated toggles, both roles, invalid images and failure latch");
}

